policy:
{
  // node:os / node:tsVersion are built in (lesson 11). attrConfig lets you
  // declare your OWN attributes; each device carries values for them in the
  // snapshot (see the posture popover). Tailground compares them just like the
  // node:* ones — string equality, numeric <>=, in [ … ], && / ||.
  //
  // No checklist — the tests block runs without posture. Watch the matrix and
  // the posture panel:
  //   1. define posture:trusted as  custom:env == 'prod'  AND  custom:riskScore < '50'
  //   2. add  "srcPosture": ["posture:trusted"]  to the grant
  //   Then only alice-trusted keeps access; alice-risky (score 90) and bob-dev
  //   (env dev) are dropped.
  "attrConfig": {
    "custom:env": { "type": "string" },
    "custom:riskScore": { "type": "number" },
  },
  "postures": {
  },
  "groups": {
    "group:eng": ["alice@example.com", "bob@example.com"],
  },
  "tagOwners": {
    "tag:secrets": ["group:eng"],
  },
  "grants": [
    { "src": ["group:eng"], "dst": ["tag:secrets"], "ip": ["tcp:443"] },
  ],
}
